  ('PENDING-COMFREY-1OZ', 'comfrey-salve-1oz-vanilla', 'bodycare', '{"en":"Organic Comfrey Salve — Vanilla","es":"Bálsamo de Consuelda Orgánica — Vainilla"}'::jsonb, '{"en":"For joints, muscles, and dry skin.","es":"Para articulaciones, músculos y piel seca."}'::jsonb, '{"en":"Organic comfrey extract blended with grass-fed beef tallow and jojoba oil, softened with warm vanilla for an easier daily ritual.","es":"Extracto orgánico de consuelda con sebo grass-fed y aceite de jojoba, suavizado con vainilla cálida para un ritual diario más agradable."}'::jsonb, '[{"en":"Grass-fed beef tallow","es":"Sebo de res grass-fed"},{"en":"Jojoba oil","es":"Aceite de jojoba"},{"en":"Organic comfrey extract","es":"Extracto orgánico de consuelda"},{"en":"Vanilla extract","es":"Extracto de vainilla"}]'::jsonb, 0, '1 oz', 'https://images.unsplash.com/photo-1617714651703-d4e8b66efb73?w=800&h=900&q=90&auto=format&fit=crop', null, false, 'comfrey-salve', 'Vanilla', 'comfrey-salve-1oz', '[{"en":"Traditional \"knitbone\" herb, organic","es":"Hierba tradicional \"suelda huesos\", orgánica"},{"en":"Whipped light, fast-absorbing texture","es":"Textura batida, ligera, absorción rápida"},{"en":"Warm vanilla scent","es":"Aroma cálido a vainilla"}]'::jsonb, null, '{"en":"Massage a small amount into the area of concern 1–2 times daily. For external use only.","es":"Masajea una pequeña cantidad en la zona de interés 1–2 veces al día. Solo para uso externo."}'::jsonb, '[{"text":{"en":"This salve is practical, whipped-texture and fast-absorbing, easy to apply on joints or muscles.","es":"Este bálsamo es práctico, de textura batida y absorción rápida, fácil de aplicar en articulaciones o músculos."},"author":"Cheyenne","location":"Jackson Township, MO"}]'::jsonb, 11),
  ('B0DX7J7N6B', 'hair-growth-oil', 'hair', '{"en":"Scalp & Hair Growth Oil","es":"Aceite para el Cuero Cabelludo y Crecimiento Capilar"}'::jsonb, '{"en":"Stronger roots. Visible growth.","es":"Raíces más fuertes. Crecimiento visible."}'::jsonb, '{"en":"Ultrasonic micronized rosemary, nettle, peppermint, and jojoba oil. Particles broken down for deeper follicle penetration. Non-greasy. Includes a free silicone scalp massager and a black satin bonnet.","es":"Romero, ortiga, menta y jojoba micronizados con ultrasonido para mayor penetración. No graso. Incluye de regalo un masajeador de cuero cabelludo de silicona y un gorro de satén negro."}'::jsonb, '[{"en":"Rosemary extract","es":"Extracto de romero"},{"en":"Nettle extract","es":"Extracto de ortiga"},{"en":"Peppermint oil","es":"Aceite de menta"},{"en":"Jojoba oil","es":"Aceite de jojoba"}]'::jsonb, 38.97, '2 oz', 'https://images.unsplash.com/photo-1527799820374-87036042f89f?w=800&h=900&q=90&auto=format&fit=crop', '{"en":"New","es":"Nuevo"}'::jsonb, true, null, null, null, '[{"en":"Ultrasonic micronized for deeper penetration","es":"Micronizado con ultrasonido para mayor penetración"},{"en":"Non-greasy, no heavy residue","es":"No graso, sin residuo pesado"}]'::jsonb, '{"en":"Free silicone scalp massager + black satin bonnet","es":"Masajeador de silicona + gorro de satén negro de regalo"}'::jsonb, '{"en":"Apply a few drops directly to the scalp and work in with the included silicone massager in circular motions for 2–3 minutes. Cover with the included satin bonnet — leave it on for 20+ minutes before rinsing for deeper absorption, or sleep in it all night for a deeper overnight treatment. Unlike cotton, satin won''t soak up the oil or rub against your hair, so the treatment stays on your scalp (not your pillow) and your hair wakes up smooth instead of frizzed or broken from friction. Use 3–4 times per week.","es":"Aplica unas gotas directo en el cuero cabelludo y masajea en círculos con el masajeador de silicona incluido por 2–3 minutos. Cubre con el gorro de satén incluido — déjalo puesto 20+ minutos antes de enjuagar para mayor absorción, o duerme con él toda la noche para un tratamiento más profundo. A diferencia del algodón, el satén no absorbe el aceite ni genera fricción con tu cabello, así que el tratamiento se queda en tu cuero cabelludo (no en tu almohada) y tu cabello amanece liso, sin frizz ni rotura por fricción. Usa 3–4 veces por semana."}'::jsonb, '[]'::jsonb, 12),
  ('B0FMQPDLFN', 'sea-salt-spray-her', 'hair', '{"en":"Organic Sea Salt Spray — For Her","es":"Spray de Sal Marina Orgánica — Para Ella"}'::jsonb, '{"en":"Volume and texture, nothing artificial.","es":"Volumen y textura, sin nada artificial."}'::jsonb, '{"en":"Ancient sea salt from Utah''s inland sea. No microplastics, no dyes, no synthetic fragrance. Matte finish, non-sticky. Works on all hair types.","es":"Sal marina antigua del mar interior de Utah. Sin microplásticos, sin colorantes, sin fragancia sintética. Acabado mate, no pegajoso."}'::jsonb, '[{"en":"Ancient Utah sea salt","es":"Sal marina antigua de Utah"},{"en":"Purified water","es":"Agua purificada"},{"en":"Natural minerals","es":"Minerales naturales"}]'::jsonb, 13.98, '8 oz — For Her', 'https://images.unsplash.com/photo-1505118380757-91f5f5632de0?w=800&h=900&q=90&auto=format&fit=crop', null, true, 'sea-salt-spray', null, null, '[{"en":"Ancient inland sea salt — no microplastics","es":"Sal de mar interior antiguo — sin microplásticos"},{"en":"Matte finish, non-sticky","es":"Acabado mate, no pegajoso"},{"en":"Works on all hair types","es":"Funciona en todo tipo de cabello"}]'::jsonb, null, '{"en":"Spray into damp or dry hair from mid-length to ends. Scrunch or twist for texture. Reapply as needed.","es":"Rocía sobre cabello húmedo o seco, desde el medio hasta las puntas. Enrosca o presiona para dar textura. Reaplica si es necesario."}'::jsonb, '[]'::jsonb, 13),
  ('B0FMQPDLFN-M', 'sea-salt-spray-him', 'hair', '{"en":"Organic Sea Salt Spray — For Him","es":"Spray de Sal Marina Orgánica — Para Él"}'::jsonb, '{"en":"Volume and texture, nothing artificial.","es":"Volumen y textura, sin nada artificial."}'::jsonb, '{"en":"Ancient sea salt from Utah''s inland sea. No microplastics, no dyes, no synthetic fragrance. Matte finish, non-sticky. Works on all hair types.","es":"Sal marina antigua del mar interior de Utah. Sin microplásticos, sin colorantes, sin fragancia sintética. Acabado mate, no pegajoso."}'::jsonb, '[{"en":"Ancient Utah sea salt","es":"Sal marina antigua de Utah"},{"en":"Purified water","es":"Agua purificada"},{"en":"Natural minerals","es":"Minerales naturales"}]'::jsonb, 13.98, '8 oz — For Him', 'https://images.unsplash.com/photo-1505118380757-91f5f5632de0?w=800&h=900&q=90&auto=format&fit=crop', null, true, 'sea-salt-spray', null, null, '[{"en":"Ancient inland sea salt — no microplastics","es":"Sal de mar interior antiguo — sin microplásticos"},{"en":"Matte finish, non-sticky","es":"Acabado mate, no pegajoso"},{"en":"Works on all hair types","es":"Funciona en todo tipo de cabello"}]'::jsonb, null, '{"en":"Spray into damp or dry hair from mid-length to ends. Scrunch or twist for texture. Reapply as needed.","es":"Rocía sobre cabello húmedo o seco, desde el medio hasta las puntas. Enrosca o presiona para dar textura. Reaplica si es necesario."}'::jsonb, '[]'::jsonb, 14),
  ('B0FHJB99W4', 'hummingbird-nectar', 'home', '{"en":"Organic Hummingbird Nectar","es":"Néctar Orgánico para Colibríes"}'::jsonb, '{"en":"Pure nectar. No dyes. No boiling.","es":"Néctar puro. Sin colorantes. Sin hervir."}'::jsonb, '{"en":"100% organic powder, dissolves instantly in water. No dyes, no preservatives, no additives. Each 8oz pouch makes 64oz of nectar. 4-pack for full garden coverage.","es":"Polvo 100% orgánico, se disuelve al instante en agua. Sin colorantes, sin conservantes. Cada bolsa de 8oz hace 64oz de néctar. Pack de 4."}'::jsonb, '[{"en":"Organic cane sugar","es":"Azúcar de caña orgánica"},{"en":"Purified water","es":"Agua purificada"}]'::jsonb, 22.97, '4-Pack / 8 oz each', 'https://images.unsplash.com/photo-1552728089-57bdde30beb3?w=800&h=900&q=90&auto=format&fit=crop', null, true, null, null, null, '[{"en":"Dissolves instantly — no boiling","es":"Se disuelve al instante — sin hervir"},{"en":"No dyes, no preservatives","es":"Sin colorantes, sin conservantes"},{"en":"Each pouch makes 64oz of nectar","es":"Cada bolsa rinde 64oz de néctar"}]'::jsonb, null, '{"en":"Empty one pouch into a clean feeder and add 8 cups of water. Stir until dissolved. Replace every 3–4 days.","es":"Vacía una bolsa en un bebedero limpio y agrega 8 tazas de agua. Revuelve hasta disolver. Cambia cada 3–4 días."}'::jsonb, '[{"text":{"en":"Just two ingredients, organic cane sugar and water, no additives or dyes.","es":"Solo dos ingredientes, azúcar de caña orgánica y agua, sin aditivos ni colorantes."},"author":"Amy","location":"Hetford County, NC"},{"text":{"en":"Dissolves instantly, good yield, no need to boil water.","es":"Se disuelve al instante, buen rendimiento, no hace falta hervir agua."},"author":"Joshua","location":"San Bernardino, CA"},{"text":{"en":"Shipping is calculated separately at checkout, not included in the listed price.","es":"El envío se calcula por separado en el checkout, no está incluido en el precio listado."},"author":"River","location":"Bend, OR"}]'::jsonb, 15),
  ('B0FBHD84ZX', 'methylene-blue', 'hoff', '{"en":"Methylene Blue 1%","es":"Azul de Metileno 1%"}'::jsonb, '{"en":"Pharmaceutical grade. Precision formula.","es":"Grado farmacéutico. Fórmula de precisión."}'::jsonb, '{"en":"USP pharmaceutical grade methylene blue. 1% concentration in a 2oz dropper bottle. No formaldehyde, no alcohol, gluten-free. For technical and research applications.","es":"Azul de metileno grado farmacéutico USP. Concentración 1% en frasco gotero de 59ml. Sin formaldehído, sin alcohol, libre de gluten."}'::jsonb, '[{"en":"Methylene blue USP","es":"Azul de metileno USP"},{"en":"Purified water","es":"Agua purificada"}]'::jsonb, 24.97, '2 oz / 59 ml', 'https://images.unsplash.com/photo-1587854692152-cbe660dbde88?w=800&h=900&q=90&auto=format&fit=crop', null, true, null, null, null, '[{"en":"USP pharmaceutical grade","es":"Grado farmacéutico USP"},{"en":"No formaldehyde, no alcohol","es":"Sin formaldehído, sin alcohol"},{"en":"Gluten-free","es":"Libre de gluten"}]'::jsonb, null, '{"en":"Use strictly according to the product label. Consult a healthcare provider before use.","es":"Usar estrictamente según la etiqueta del producto. Consulta a un profesional de salud antes de usar."}'::jsonb, '[{"text":{"en":"Pharmaceutical USP grade, no formaldehyde or alcohol, which is a serious quality standard.","es":"Grado USP farmacéutico, sin formaldehído ni alcohol, lo cual es un estándar serio de calidad."},"author":"Sedona","location":"Sandford, ME"},{"text":{"en":"The label recommends consulting a doctor before use, which is a good thing given the nature of the product.","es":"La etiqueta recomienda consultar a un médico antes de usarlo, algo positivo dada la naturaleza del producto."},"author":"Orion","location":"Oak Hill, WV"},{"text":{"en":"It''s a delicate substance that can interact with medications like antidepressants, so it''s not something to take lightly.","es":"Es una sustancia delicada que puede interactuar con medicamentos como antidepresivos, así que no es para tomarla a la ligera."},"author":"Mason","location":"Seymour, IN"}]'::jsonb, 16)
